+        after: operation::AfterOperation,
+    ) -> Result<Self, CommandError> {
+        let prev = Self::current(world, name)?;
+        let next = Operation { after, ..prev.clone() };
+        Ok(EditOperationParams { name: name.to_string(), prev, next })
+    }
